# -*- coding: utf-8 -*-
# (speaker, italian, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
F, H, A, MT, G, T = "Filippo", "Hélène", "Arnaud", "Matteo", "Graziella", "Tassista"
D = [
("#", "Scena 1 — Venerdì 7 febbraio, ore 8.10. Un taxi da Orly verso il centro di Parigi.", "장면 1 — 2월 7일 금요일 오전 8시 10분. 오를리 공항에서 파리 시내로 가는 택시."),
(None, "Pioggerella fine sul périphérique. Filippo, cappotto grigio e borsa da lavoro sulle ginocchia, rilegge per la terza volta la stessa pagina. Il tassista lo osserva dallo specchietto.", "외곽 순환도로에 보슬비가 내린다. 회색 코트를 입은 필리포가 서류 가방을 무릎에 올려놓고 같은 페이지를 세 번째 읽고 있다. 택시 기사가 백미러로 그를 본다."),
(T, "Lei è italiano, vero? L'ho sentito al telefono, in aeroporto. Anch'io: Catania. Trent'anni a Parigi.", "이탈리아 분이시죠? 공항에서 통화하시는 거 들었어요. 저도요. 카타니아 출신, 파리에서 30년째예요."),
(F, "Toscano. Scandicci, vicino a Firenze.", "토스카나 사람이에요. 피렌체 근처 스칸디치."),
(T, "Pelle, allora. Da voi fate tutti borse. Viene a vendere o a comprare?", "그럼 가죽이네요. 거기선 다들 가방 만들잖아요. 팔러 오셨어요, 사러 오셨어요?"),
(F, "A non perdere. Che è un'altra cosa.", "안 잃으러 왔어요. 그건 또 다른 일이죠."),
(T, "(ride) Allora in bocca al lupo, dottore. Faubourg Saint-Honoré fra venti minuti, se il périphérique ci lascia passare.", "(웃으며) 그럼 행운을 빌어요, 선생님. 순환도로가 길만 열어 주면 포부르 생토노레까지 20분이에요."),
(F, "Crepi. (vibra il telefono) Mi scusi... Pronto, mamma.", "고마워요. (휴대폰이 진동한다) 실례합니다... 여보세요, 엄마."),
(G, "Sei arrivato? Hai mangiato qualcosa?", "도착했니? 뭐라도 먹었어?"),
(F, "Un caffè in aeroporto. Mamma, sono le otto.", "공항에서 커피 한 잔이요. 엄마, 지금 8시예요."),
(G, "Appunto. A stomaco vuoto non si tratta. Tuo padre, a Parigi, faceva colazione al bar sotto la Maison. Sempre lo stesso.", "그러니까. 빈속으로는 협상 못 해. 너희 아버지는 파리에 가면 메종 건물 아래 바에서 아침을 먹었어. 늘 같은 곳에서."),
(F, "Lo so. Il bar c'è ancora. Ci passo.", "알아요. 그 바 아직 있어요. 들를게요."),
(G, "Ricordati quello che abbiamo deciso. Trenta, tre, e due anni di volumi garantiti. Sotto quello non firmi niente.", "우리가 정한 거 기억해. 30, 3, 그리고 2년 물량 보장. 그보다 못하면 아무것도 서명하지 마."),
(F, "E se Hélène non scende dal quaranta?", "엘렌이 40에서 안 내려오면요?"),
(G, "Allora torni a casa e ne parliamo domenica. Tutti e tre. Come d'accordo.", "그럼 집에 와서 일요일에 얘기하자. 셋이 다 같이. 약속한 대로."),
(F, "Mamma, a volte una trattativa si chiude in una stanza, non a tavola.", "엄마, 협상은 가끔 식탁이 아니라 회의실에서 끝나기도 해요."),
(G, "Le trattative di questa famiglia si sono sempre chiuse a tavola, Filippo. Anche quelle di tuo padre. A Parigi firmava una bozza, e la firma vera la metteva a casa.", "이 집안의 협상은 늘 식탁에서 끝났어, 필리포. 너희 아버지 것도. 아버지는 파리에서는 초안에만 서명하고, 진짜 서명은 집에서 했어."),
(F, "Una bozza. D'accordo. Firmo solo una bozza.", "초안이요. 알겠어요. 초안에만 서명할게요."),
(G, "Bravo. E chiama Matteo prima di accettare qualsiasi clausola sul marchio. Quella è roba sua.", "잘했어. 그리고 브랜드 관련 조항은 받아들이기 전에 마테오한테 전화해. 그건 걔 일이야."),
(F, "(sospira) Lo chiamerò. Ciao, mamma.", "(한숨을 쉬며) 전화할게요. 끊어요, 엄마."),
(None, "Il tassista sorride nello specchietto e alza il volume della radio: una canzone di Battiato.", "택시 기사가 백미러 속에서 미소 짓고 라디오 볼륨을 올린다. 바티아토의 노래가 흐른다."),

("#", "Scena 2 — Ore 9.30. Sede della Maison Varenne, sala riunioni al quarto piano.", "장면 2 — 오전 9시 30분. 메종 바렌 본사, 4층 회의실."),
(None, "Una sala bianca, un lungo tavolo di vetro. Alla parete, la foto in bianco e nero di una borsa Varenne del 1962. Entra Hélène Dufresne, una cinquantina d'anni, tailleur blu, seguita da un uomo più giovane con un fascicolo sotto il braccio.", "하얀 회의실, 긴 유리 테이블. 벽에는 1962년 바렌 가방의 흑백 사진. 쉰 살 남짓, 파란 정장의 엘렌 뒤프렌이 들어오고, 서류철을 낀 젊은 남자가 뒤따른다."),
(H, "Filippo, bonjour. Grazie di essere venuto fino a Parigi. Le presento Arnaud Ferrand, del nostro ufficio legale.", "필리포, 봉주르. 파리까지 와 주셔서 고마워요. 저희 법무팀의 아르노 페랑을 소개할게요."),
(A, "Piacere, dottor Corsini. Ho lavorato due anni a Milano, quindi possiamo parlare italiano tranquillamente.", "반갑습니다, 코르시니 씨. 밀라노에서 2년 일해서 이탈리아어로 편하게 얘기하셔도 됩니다."),
(F, "Piacere mio. Meglio così: il mio francese si ferma ai menù.", "반갑습니다. 다행이네요. 제 프랑스어는 메뉴판 수준이라서요."),
(H, "Alors, cominciamo. Lei conosce la nostra posizione: quaranta per cento in meno sulla primavera-estate, cinque per cento sui prezzi unitari.", "자, 시작하죠. 저희 입장은 아시죠. 봄·여름 물량 40퍼센트 축소, 단가 5퍼센트 인하."),
(F, "La conosco. E Lei conosce la mia: trenta e tre.", "압니다. 그리고 제 입장도 아시죠. 30과 3."),
(H, "Filippo, Lei sa che non decido da sola. Il nostro direttore finanziario vuole risparmiare quattro milioni quest'anno sulla pelletteria.", "필리포, 제가 혼자 결정하는 게 아니란 거 아시잖아요. 저희 재무 이사가 올해 가죽 제품에서 400만 유로를 줄이고 싶어 해요."),
(F, "E vuole risparmiarli tutti a Scandicci.", "그걸 전부 스칸디치에서 줄이고 싶은 거고요."),
(H, "Non tutti. Ma una parte importante, sì. Voi siete il nostro fornitore principale per la pelletteria.", "전부는 아니에요. 하지만 상당 부분은 맞아요. 가죽 제품은 그쪽이 저희 주력 공급업체니까요."),
(F, "Appunto. Lo siamo da diciannove anni. Mi permetta di mostrarLe tre numeri, prima di parlare di percentuali.", "바로 그거예요. 19년째 그렇죠. 퍼센트 얘기 전에 숫자 세 개를 보여 드려도 될까요?"),
(H, "Prego.", "그러세요."),
(F, "Primo: l'anno scorso il nostro tasso di difettosità è stato dello zero virgola quattro per cento. Il vostro standard è l'uno.", "첫째, 작년 저희 불량률은 0.4퍼센트였습니다. 그쪽 기준은 1퍼센트고요."),
(H, "Lo so. Lo vedo nei rapporti del controllo qualità.", "알아요. 품질 검사 보고서에서 보고 있어요."),
(F, "Secondo: in diciannove anni non abbiamo mai consegnato in ritardo una collezione. Mai.", "둘째, 19년 동안 컬렉션 납기를 한 번도 어긴 적이 없습니다. 단 한 번도."),
(H, "Anche questo è vero.", "그것도 사실이에요."),
(F, "Terzo: per qualificare un nuovo fornitore vi servono almeno due stagioni. Prototipi, audit, prove di produzione. Il fornitore portoghese con cui state parlando... quante borse vi ha già consegnato?", "셋째, 새 공급업체를 인증하려면 적어도 두 시즌이 필요합니다. 시제품, 감사, 시험 생산. 지금 얘기 중인 포르투갈 업체는... 벌써 가방을 몇 개나 납품했나요?"),
(None, "Hélène e Arnaud si scambiano un'occhiata.", "엘렌과 아르노가 눈빛을 주고받는다."),
(H, "Vedo che le notizie da Pitti viaggiano veloci.", "피티 소식이 빨리 퍼지는군요."),
(F, "Pitti è piccola. Prima o poi ci si incontra tutti al bar.", "피티는 좁아요. 언젠가는 다들 바에서 마주치죠."),
(H, "Non nego che ci siano dei contatti. Ma il Portogallo costa il venti per cento in meno. E il nostro direttore finanziario le moltiplicazioni le sa fare.", "접촉이 있다는 건 부정하지 않아요. 하지만 포르투갈은 20퍼센트 싸요. 그리고 저희 재무 이사는 곱셈을 할 줄 알죠."),
(F, "Il Portogallo costa il venti per cento in meno oggi. Fra un anno, con i resi, i ritardi e le borse da rifare, quanto costerà?", "포르투갈은 오늘 20퍼센트 싸죠. 1년 뒤에 반품, 지연, 다시 만들 가방까지 따지면 얼마가 될까요?"),
(A, "Se permette, dottor Corsini: questo è un rischio che valutiamo noi.", "실례지만, 코르시니 씨, 그건 저희가 판단할 위험입니다."),
(F, "Certo. Io mi limito a ricordarvelo.", "물론이죠. 저는 상기시켜 드릴 뿐입니다."),
(H, "Bon. Facciamo così. Il taglio: trentacinque per cento.", "좋아요. 이렇게 하죠. 축소는 35퍼센트."),
(F, "Trenta.", "30."),
(H, "Trentacinque, Filippo. Ho già dovuto litigare per arrivare fin qui.", "35예요, 필리포. 여기까지 오는 데도 이미 싸워야 했어요."),
(F, "Trenta, ma con una garanzia di volumi per due anni. Se mi garantite i volumi, posso accettare un taglio forte adesso, perché so cosa succede dopo. Senza garanzia, ogni stagione è una roulette.", "30. 대신 2년 물량 보장을 붙여서요. 물량을 보장해 주시면 지금 큰 축소도 받아들일 수 있어요. 그 뒤에 무슨 일이 생길지 아니까요. 보장이 없으면 매 시즌이 룰렛이죠."),
(H, "Una garanzia di volumi... per quanto tempo, esattamente?", "물량 보장이라... 정확히 얼마 동안이요?"),
(F, "Due anni. Primavera-estate e autunno-inverno, al livello di oggi dopo il taglio. Neanche un pezzo di meno.", "2년이요. 봄·여름, 가을·겨울 모두, 이번 축소 후 수준으로. 한 개도 덜어 내지 않고요."),
(H, "(prende appunti) Se vi garantissi due anni, il direttore finanziario vorrebbe in cambio il cinque per cento sul prezzo.", "(메모하며) 2년을 보장해 드린다면, 재무 이사는 대신 가격 5퍼센트를 원할 거예요."),
(F, "Tre.", "3."),
(H, "Quattro.", "4."),
(F, "Tre, Hélène. Con il tre per cento e due anni garantiti, posso tenere al lavoro tutti. Con il quattro, a giugno devo mettere venti persone in cassa integrazione. E queste cose, a Scandicci, si vengono a sapere. Anche a Parigi.", "3이에요, 엘렌. 3퍼센트에 2년 보장이면 모두 일하게 할 수 있어요. 4면 6월에 스무 명을 휴업시켜야 해요. 그런 일은 스칸디치에서 다 알려져요. 파리에도요."),
(H, "È una minaccia?", "협박인가요?"),
(F, "È un fatto. Mia madre l'ha detto a tavola: nessuno va in cassa integrazione. Io devo trovare il modo di mantenere la sua promessa.", "사실이에요. 어머니가 식탁에서 말씀하셨어요. 아무도 휴업시키지 않는다고. 저는 그 약속을 지킬 방법을 찾아야 해요."),
(H, "(un piccolo sorriso) Sua madre. La signora Graziella. Me la ricordo alla cena per i cinquant'anni della vostra azienda. Mi disse: « Le nostre borse le fanno le mani, non le macchine. »", "(살짝 미소 지으며) 어머님. 그라치엘라 여사님. 그쪽 회사 50주년 만찬에서 뵌 기억이 나요. 저한테 '우리 가방은 기계가 아니라 손이 만든다'고 하셨죠."),
(F, "Lo dice ancora. Tutte le domeniche.", "아직도 그러세요. 일요일마다요."),
(H, "Bon. Trenta per cento, tre per cento, due anni di volumi garantiti. Posso portarlo al direttore finanziario. Ma vorrà qualcosa in cambio.", "좋아요. 30퍼센트, 3퍼센트, 2년 물량 보장. 재무 이사에게 가져갈 수 있어요. 하지만 그쪽도 뭔가를 원할 거예요."),
(F, "Che cosa?", "뭘요?"),
(A, "Un impegno di riservatezza rafforzato. E una nuova versione dell'articolo sette, la clausola di non concorrenza.", "강화된 비밀유지 의무. 그리고 경업 금지 조항인 제7조의 새 문안입니다."),
(F, "Cioè?", "그게 무슨 뜻이죠?"),
(A, "Ci risulta che la vostra famiglia voglia sviluppare il marchio Corsini 1958 all'estero. In Corea, in particolare.", "저희가 알기로는 그쪽 가족이 'Corsini 1958' 브랜드를 해외에서 키우려 한다더군요. 특히 한국에서요."),
(F, "(pausa) Vedo che anche le notizie da Seul viaggiano veloci.", "(잠시 침묵) 서울 소식도 빨리 퍼지는군요."),
(A, "Il mondo del lusso è piccolo quanto Pitti, dottore. L'articolo sette, così com'è scritto, vi vieta qualsiasi pelletteria in concorrenza con noi, in qualsiasi paese. Siamo disposti a riscriverlo. Ma prima vogliamo essere sicuri di tre cose.", "명품 업계는 피티만큼 좁습니다, 선생님. 지금 문구대로라면 제7조는 어느 나라에서든 저희와 경쟁하는 가죽 제품을 모두 금지합니다. 저희는 그 조항을 다시 쓸 의향이 있습니다. 다만 먼저 세 가지를 확실히 해 두고 싶습니다."),
(F, "Mi dica quali.", "말씀해 보세요."),
(A, "Primo: nessun modello Corsini deve essere confondibile con un modello Varenne. Secondo: niente pellami né accessori realizzati in esclusiva per noi. Terzo, ed è il più importante: in nessuna comunicazione dovete dire, o lasciar capire, che producete per la Maison.", "첫째, 코르시니의 어떤 모델도 바렌 모델과 혼동되어서는 안 됩니다. 둘째, 저희 전용으로 만든 가죽이나 부자재는 쓰지 않습니다. 셋째, 이게 가장 중요한데, 어떤 홍보에서도 메종 제품을 생산한다고 말하거나 암시해서는 안 됩니다."),
(F, "Il terzo punto... prima di rispondere devo sentire una persona. Possiamo fare dieci minuti di pausa?", "세 번째는... 답하기 전에 한 사람과 얘기해야겠습니다. 10분만 쉬어도 될까요?"),
(H, "Facciamone quindici. La macchinetta del caffè è in fondo al corridoio. Il caffè è terribile, La avverto.", "15분 쉬죠. 커피 자판기는 복도 끝에 있어요. 커피는 끔찍하니 미리 말씀드려요."),

("#", "Scena 3 — Ore 11.15. Il corridoio, davanti alla macchinetta del caffè.", "장면 3 — 오전 11시 15분. 복도, 커피 자판기 앞."),
(None, "Filippo preme un tasto, guarda il bicchierino di plastica riempirsi, lo lascia lì. Chiama.", "필리포가 버튼을 누르고, 플라스틱 컵이 차오르는 것을 보다가 그대로 둔다. 전화를 건다."),
(F, "Matteo, hai cinque minuti? Sono alla Maison.", "마테오, 5분 있어? 메종이야."),
(MT, "Per te anche dieci. Com'è andata?", "형한테는 10분도 돼. 어떻게 됐어?"),
(F, "Trenta, tre e due anni garantiti. Credo che passi.", "30, 3, 그리고 2년 보장. 통과될 것 같아."),
(MT, "Trenta e tre? Filippo, è un miracolo. Come hai fatto?", "30이랑 3? 형, 기적이네. 어떻게 한 거야?"),
(F, "Con i numeri. E con la mamma, a dire il vero. Ma c'è un prezzo. Vogliono una clausola sul nostro marchio all'estero.", "숫자로. 솔직히 말하면 엄마 덕도 있고. 근데 대가가 있어. 해외에서의 우리 브랜드에 관한 조항을 원해."),
(MT, "Che clausola?", "무슨 조항?"),
(F, "L'articolo sette, scritto com'è, ci vieta tutto, dappertutto. Sono disposti a riscriverlo, ma con tre condizioni. Niente modelli che somiglino ai loro. Niente pelli e accessori esclusivi loro. E non dire mai che produciamo per la Maison.", "지금 문구대로면 제7조가 우리한테 어디서든 다 금지하고 있어. 그걸 다시 써 줄 의향은 있는데, 조건이 셋이야. 그쪽 모델과 비슷한 거 금지. 그쪽 전용 가죽과 부자재 금지. 그리고 메종 제품을 만든다는 말은 절대 하지 말 것."),
(MT, "Le prime due sono giuste. Le avremmo rispettate comunque. La terza...", "앞의 두 개는 당연해. 어차피 지켰을 거고. 세 번째는..."),
(F, "La terza è proprio quella che volevi usare tu. « Le borse Varenne le facciamo noi. » Giulia l'ha detto a tavola.", "세 번째가 바로 네가 써먹고 싶던 거잖아. '바렌 가방은 우리가 만든다.' 줄리아가 식탁에서 그랬지."),
(MT, "Lo so. Ma tre giorni fa, nella videochiamata, la signora Kim ha detto la stessa cosa a Chiara: che è meglio non dirlo. Che la nostra storia è più bella senza di loro.", "알아. 근데 사흘 전 화상 통화에서 김서연 씨가 누나한테 똑같은 말을 했어. 그 말은 안 하는 게 좋다고. 우리 이야기는 그들 없이도 더 아름답다고."),
(F, "La buyer coreana ha detto questo?", "그 한국 바이어가 그런 말을 했다고?"),
(MT, "Sì. E aveva ragione. Il nostro racconto è Scandicci, il nonno Ugo, le undici ore per una borsa. Non abbiamo bisogno di attaccarci all'etichetta di un altro.", "응. 그리고 맞는 말이었어. 우리 이야기는 스칸디치, 우고 할아버지, 가방 하나에 열한 시간이야. 남의 라벨에 기댈 필요 없어."),
(F, "Quindi posso accettare?", "그럼 받아들여도 되는 거지?"),
(MT, "Puoi accettare. Ma l'articolo sette fallo scrivere stretto: non concorrenza solo in Francia, e solo per i modelli fatti per Varenne. La Francia è casa loro, a noi non serve. E fai scrivere che possiamo dire di essere un laboratorio artigiano di Scandicci dal 1958 che lavora anche per grandi marchi del lusso. Senza nominarli. In Toscana lo sanno tutti.", "받아들여도 돼. 대신 제7조는 좁게 쓰게 해. 경업 금지는 프랑스에서만, 그리고 바렌을 위해 만든 모델에만. 프랑스는 그쪽 안방이고 우린 필요 없어. 그리고 우리가 1958년부터 스칸디치의 장인 공방이고 명품 브랜드 일도 한다고 말할 수 있게 적어 줘. 이름은 빼고. 토스카나에선 다 아는 일이니까."),
(F, "Solo Francia, solo i modelli Varenne. E « anche per grandi marchi », senza nomi. Va bene. Lo chiedo.", "프랑스만, 바렌 모델만. 그리고 '명품 브랜드 일도', 이름 없이. 좋아. 요청할게."),
(MT, "E Filippo... grazie di avermi chiamato.", "그리고 형... 전화해 줘서 고마워."),
(F, "Me l'ha ordinato la mamma.", "엄마가 시켰어."),
(MT, "Lo so. Grazie lo stesso.", "알아. 그래도 고마워."),
(None, "Filippo chiude la telefonata e resta un attimo immobile davanti alla macchinetta. Poi beve il caffè. È davvero terribile.", "필리포는 전화를 끊고 자판기 앞에 잠시 가만히 서 있다. 그러고는 커피를 마신다. 정말 끔찍한 맛이다."),

("#", "Scena 4 — Ore 11.40. Di nuovo in sala riunioni. Poi l'ascensore e la strada.", "장면 4 — 오전 11시 40분. 다시 회의실. 그리고 엘리베이터와 거리."),
(F, "Ho parlato con mio fratello. Accettiamo le tre condizioni. In cambio, l'articolo sette vale solo per la Francia e solo per i modelli realizzati per Varenne. E una precisazione sulla comunicazione.", "동생과 얘기했습니다. 세 가지 조건 받아들이겠습니다. 그 대신 제7조는 프랑스에서만, 그리고 바렌을 위해 만든 모델에만 적용합니다. 그리고 홍보에 관해 단서를 하나 달겠습니다."),
(A, "Prego.", "말씀하세요."),
(F, "Nella nostra comunicazione potremo dire che siamo un laboratorio di Scandicci dal 1958 e che lavoriamo anche per marchi del lusso. Senza nomi, senza loghi, senza allusioni.", "저희 홍보에서 1958년부터 스칸디치의 공방이며 명품 브랜드 일도 한다고는 말할 수 있게 해 주십시오. 이름도, 로고도, 암시도 없이요."),
(A, "(scrive) « Articolo sette: territorio francese, limitatamente ai modelli realizzati per la Maison. » E: « Anche per primarie maison del lusso, senza indicazione di nomi o segni distintivi. » Mi sembra accettabile. Hélène?", "(받아 적으며) '제7조: 프랑스 영토, 메종을 위해 제작된 모델에 한함.' 그리고 '이름이나 식별 표지 없이, 주요 명품 메종의 일도 한다.' 받아들일 만해 보입니다. 엘렌?"),
(H, "Accettabile. La Francia è casa nostra: lì non vi voglio vedere. Il resto del mondo è grande. E l'importante è che nessuno scriva il nostro nome sotto la foto di una vostra borsa.", "받아들일 만해요. 프랑스는 저희 안방이니 거기선 안 보였으면 해요. 나머지 세상은 넓잖아요. 그리고 중요한 건 누구도 그쪽 가방 사진 밑에 저희 이름을 쓰지 않는 거예요."),
(F, "Non succederà. Lo garantisco io.", "그런 일은 없을 겁니다. 제가 보장합니다."),
(H, "E in cambio la Maison ha bisogno di una cosa che non è nel fascicolo di Arnaud.", "그리고 그 대가로 메종은 아르노 서류철에 없는 걸 하나 필요로 해요."),
(F, "Ecco. Lo sapevo.", "그렇죠. 그럴 줄 알았어요."),
(H, "Niente di terribile. Per l'autunno-inverno stiamo preparando una borsa nuova, molto difficile. Bordi dipinti, cuciture a mano. Il Portogallo non è in grado di farla. Voi sì.", "끔찍한 건 아니에요. 가을·겨울용으로 아주 까다로운 새 가방을 준비 중이에요. 가장자리 도장, 손바느질. 포르투갈은 못 만들어요. 그쪽은 할 수 있죠."),
(F, "Quindi il Portogallo non era una minaccia vera.", "그러니까 포르투갈은 진짜 위협이 아니었군요."),
(H, "Il Portogallo è una minaccia vera per le borse semplici, Filippo. Non per quelle difficili. Un consiglio da amica: fatevi trovare pronti sulle borse difficili. Quelle semplici, prima o poi, se ne vanno.", "포르투갈은 단순한 가방에는 진짜 위협이에요, 필리포. 까다로운 가방에는 아니고요. 친구로서 하는 충고예요. 까다로운 가방에서 늘 준비돼 있으세요. 단순한 가방은 언젠가 떠나요."),
(F, "Lo terrò a mente. Quante borse difficili?", "명심할게요. 까다로운 가방은 몇 개나요?"),
(H, "Tremila pezzi, consegna a giugno. Il prototipo entro fine marzo.", "3,000개, 6월 납품. 시제품은 3월 말까지."),
(F, "Il prototipo lo farà Renzo.", "시제품은 렌초가 만들 겁니다."),
(H, "Renzo è ancora lì? Quel signore che non sorride mai?", "렌초가 아직 거기 있어요? 절대 웃지 않는 그분?"),
(F, "Sorride. Ma solo alle borse fatte bene.", "웃어요. 잘 만든 가방한테만요."),
(H, "(ride) Allora deve sorridere spesso. Bon. Arnaud, prepari la bozza.", "(웃으며) 그럼 자주 웃으시겠네요. 좋아요. 아르노, 초안 준비해 줘요."),
(A, "In dieci minuti. Riassumo: riduzione del trenta per cento sulla primavera-estate, sconto del tre per cento sui prezzi unitari, volumi minimi garantiti per quattro stagioni, cioè due anni. Clausola di riservatezza rafforzata. Articolo sette limitato alla Francia e ai soli modelli realizzati per Varenne, con la formula concordata sulla comunicazione.", "10분이면 됩니다. 정리하겠습니다. 봄·여름 물량 30퍼센트 축소, 단가 3퍼센트 인하, 네 시즌 즉 2년간 최소 물량 보장. 강화된 비밀유지 조항. 제7조는 프랑스와 바렌용 모델에 한정하고, 합의한 홍보 문구를 넣습니다."),
(F, "E un'ultima cosa: la bozza resta una bozza fino a lunedì. La firma definitiva la mettiamo dopo una riunione di famiglia.", "그리고 마지막으로, 초안은 월요일까지 초안으로 남습니다. 최종 서명은 가족 회의 후에 하겠습니다."),
(A, "Una riunione di famiglia? Con tutto il rispetto, dottor Corsini, Lei è il direttore generale.", "가족 회의요? 실례지만 코르시니 씨, 총괄 사장이시잖습니까."),
(F, "Sono il direttore generale. Ma da noi certe firme si mettono in tre. È una regola nuova. L'ha decisa mia madre.", "총괄 사장 맞습니다. 하지만 저희는 어떤 서명은 셋이서 합니다. 새 규칙이죠. 어머니가 정하셨어요."),
(H, "(sorride) Mi saluti la signora Graziella. E le dica che a Parigi le regole delle madri si rispettano ancora.", "(미소 지으며) 그라치엘라 여사님께 안부 전해 주세요. 파리에서도 어머니의 규칙은 아직 존중받는다고 말씀드리고요."),
(None, "Venti minuti dopo, Filippo sigla la bozza con una firma piccola in fondo a ogni pagina. Hélène lo accompagna all'ascensore.", "20분 뒤, 필리포는 초안의 모든 페이지 아래에 작게 서명한다. 엘렌이 그를 엘리베이터까지 배웅한다."),
(H, "Filippo, posso darti del tu, adesso che Arnaud non ci sente?", "필리포, 아르노가 안 듣는 지금은 말 놓아도 될까?"),
(F, "Dopo diciannove anni? Direi che è ora.", "19년 만에? 그럴 때가 됐지."),
(H, "Allora te lo dico da amica, non da compratrice: la tua famiglia ha fatto bene a mandarti qui da solo. Ma ha fatto ancora meglio a non lasciarti firmare da solo.", "그럼 바이어가 아니라 친구로서 말할게. 너희 가족이 너를 혼자 보낸 건 잘한 일이야. 하지만 혼자 서명하게 두지 않은 건 더 잘한 일이야."),
(F, "Lo pensi davvero?", "정말 그렇게 생각해?"),
(H, "Mio padre aveva una piccola pelletteria a Lione. L'hanno venduta i miei fratelli, senza dirlo a nessuno. Mia madre non gliel'ha mai perdonato.", "우리 아버지는 리옹에 작은 가죽 공방이 있었어. 오빠들이 아무한테도 말 안 하고 팔아 버렸지. 엄마는 끝내 그걸 용서하지 않았어."),
(F, "Mi dispiace.", "안됐다."),
(H, "Non dispiacerti. Torna a Scandicci e fai la tua riunione di famiglia. E porta a tuo fratello i miei auguri per la Corea. Senza nomi, naturalmente.", "안돼할 거 없어. 스칸디치로 돌아가서 가족 회의 해. 그리고 동생한테 한국 일 잘되길 바란다고 전해 줘. 물론 이름은 빼고."),
(F, "(sorride) Senza nomi.", "(미소 지으며) 이름은 빼고."),
(None, "Le porte dell'ascensore si chiudono. In strada, sotto la pioggerella, Filippo compone un numero.", "엘리베이터 문이 닫힌다. 보슬비 내리는 거리에서 필리포가 번호를 누른다."),
(G, "Allora?", "그래서?"),
(F, "Trenta, tre, due anni. E una borsa difficile per l'autunno.", "30, 3, 2년. 그리고 가을용 까다로운 가방 하나."),
(G, "(un lungo silenzio) Tuo padre sarebbe stato orgoglioso.", "(긴 침묵) 너희 아버지가 자랑스러워했을 거야."),
(F, "Ho firmato solo la bozza, mamma. Come avevi detto tu.", "초안에만 서명했어요, 엄마. 엄마 말대로."),
(G, "Lo so. Domenica a pranzo, allora. Tutti e tre. E porta il contratto.", "알아. 그럼 일요일 점심에. 셋이 다 같이. 계약서 가져와."),
(F, "Porto il contratto. E un gelato per Giulia: la scommessa l'ha vinta a metà.", "계약서 가져갈게요. 줄리아 줄 젤라토도요. 내기는 반쯤 이겼으니까요."),
(G, "A metà?", "반쯤?"),
(F, "Abbiamo una firma su tre, mamma. La mia. Le altre due le mettiamo domenica.", "셋 중 하나의 서명은 있어요, 엄마. 제 거요. 나머지 둘은 일요일에 해요."),
]

PRE = [
("text", "가계도·인물 관계", "이번 화는 필리포의 시점입니다. 회사를 지키는 맏아들이 홀로 파리에 가서, 어머니의 규칙과 동생의 계획 사이에서 협상을 마무리합니다.", [
"[시점 인물] Filippo Corsini (필리포, 44) — 맏아들, 총괄 사장(direttore generale). 메종 바렌과의 19년 거래를 책임져 왔다. 이번 화에서 처음으로 '셋이 하는 서명'을 받아들인다.",
"[어머니] Graziella (그라치엘라, 68) — 회장, 지분 30%. 전화로만 등장하지만 협상의 기준선(30·3·2년)을 정한다. 남편 파올로는 '파리에선 초안, 서명은 집에서'라는 원칙이 있었다.",
"[동생] Matteo (마테오, 31) — ★주인공. 전화로 등장해 브랜드 조항의 문구를 다듬는다.",
"[사외] Hélène Dufresne (엘렌 뒤프렌) — 메종 바렌 구매 책임자. 피렌체 지사 근무 경력으로 이탈리아어가 유창하고 프랑스어 감탄사(bon, alors)가 섞인다. 필리포와 19년 거래 관계.",
"[사외] Arnaud Ferrand (아르노 페랑) — 메종 바렌 법무팀. 밀라노 근무 2년. 조항을 정확한 서면 문구로 옮기는 역할.",
"[사외] Tassista (택시 기사) — 카타니아 출신, 파리 30년. 이탈리아인끼리의 짧은 만남.",
]),
]

